<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    mock</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Mock</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // 关键：嵌入 Mock 结构体</span></span>
